MultiLanguageSpellData['en'][225522] = {name = "Glyph of Cracked Ice", additional_info = "2 sec cast\nReagents:\nLight Parchment , Sallow Pigment (10), Roseate Pigment (30)\n[q]Craft a Glyph of Cracked Ice.\nVendor:\nJang Quillpaw\nZone:\nDalaran\nCost:\n35\n\nClasses: Death Knight\n[q2]Use: Permanently teaches you this glyph.\n\nYour Path of Frost ability now looks a little cracked, just a little. Exclusive with: Glyph of Dry Ice\n11"}
MultiLanguageSpellData['en'][225524] = {name = "Glyph of the Chilled Shell", additional_info = "2 sec cast\nReagents:\nLight Parchment , Sallow Pigment (10), Roseate Pigment (30)\n[q]Craft a Glyph of the Chilled Shell.\nDrop:\nBroken Isles Water Elementals\n\n\nClasses: Death Knight\n[q2]Use: Permanently teaches you this glyph.\n\nYour Anti-Magic Shell shifts to match more of a Frost affinity. Exclusive with: Glyph of the Crimson Shell\n11"}
MultiLanguageSpellData['en'][225525] = {name = "Glyph of the Crimson Shell", additional_info = "2 sec cast\nReagents:\nLight Parchment , Sallow Pigment (10), Roseate Pigment (30)\n[q]Craft a Glyph of the Crimson Shell.\nVendor:\nJang Quillpaw\nZone:\nDalaran\nCost:\n35\n\nClasses: Death Knight\n[q2]Use: Permanently teaches you this glyph.\n\nYour Anti-Magic Shell shifts to match more of a Blood affinity. Exclusive with: Glyph of the Chilled Shell\n11"}
MultiLanguageSpellData['en'][225527] = {name = "Glyph of Fel Wings", additional_info = "2 sec cast\nReagents:\nLight Parchment , Sallow Pigment (12), Roseate Pigment (20)\n[q]Craft a Glyph of Fel Wings.\nDrop:\nBroken Isles Demon Beasts\n\n\nClasses: Demon Hunter\n[q2]Use: Permanently teaches you this glyph.\n\nYou now have green wings when Glide is active. Exclusive with: Glyph of Fallow Wings Glyph of Tattered Wings\n11"}
MultiLanguageSpellData['en'][225528] = {name = "Glyph of Fel-Enemies", additional_info = "2 sec cast\nReagents:\nLight Parchment , Sallow Pigment (12), Roseate Pigment (20)\n[q]Craft a Glyph of Fel-Enemies.\nVendor:\nJang Quillpaw\nZone:\nDalaran\nCost:\n35\n\nClasses: Demon Hunter\n[q2]Use: Permanently teaches you this glyph.\n\nYour Spectral Sight is altered by Fel energy causing you to see all enemies in a Fel light.\n11"}
MultiLanguageSpellData['en'][225529] = {name = "Glyph of Mana Touched Souls", additional_info = "2 sec cast\nReagents:\nLight Parchment , Sallow Pigment (12), Roseate Pigment (20)\n[q]Craft a Glyph of Mana Touched Souls.\nVendor:\nJang Quillpaw\nZone:\nDalaran\nCost:\n35\n\nClasses: Demon Hunter\n[q2]Use: Permanently teaches you this glyph.\n\nYour Shattered Souls are tainted with mana. Exclusive with: Glyph of Fel Touched Souls\n11"}
MultiLanguageSpellData['en'][225530] = {name = "Glyph of Shadow-Enemies", additional_info = "2 sec cast\nReagents:\nLight Parchment , Sallow Pigment (12), Roseate Pigment (20)\n[q]Craft a Glyph of Shadow-Enemies.\nVendor:\nOxana Demonslay\nZone:\nDalaran Sewers\nCost:\n100\n\nClasses: Demon Hunter\n[q2]Use: Permanently teaches you this glyph.\n\nYour Spectral Sight is tinted by the void and you see enemies shrouded in Shadow.\n11"}
MultiLanguageSpellData['en'][225531] = {name = "Glyph of the Doe", additional_info = "2 sec cast\nReagents:\nLight Parchment , Sallow Pigment (4), Roseate Pigment (60)\n[q]Craft a Glyph of the Doe.\nDrop:\nWorld Broken Isles Creatures\n\n\nClasses: Druid\n[q2]Use: Unlocks the Doe Travel Form option at the Barber Shop.\n11"}
MultiLanguageSpellData['en'][225532] = {name = "Glyph of the Feral Chameleon", additional_info = "2 sec cast\nReagents:\nLight Parchment , Sallow Pigment (4), Roseate Pigment (60)\n[q]Craft a Glyph of the Feral Chameleon.\nVendor:\nJang Quillpaw\nZone:\nDalaran\nCost:\n35\n\nClasses: Druid\n[q2]Use: Permanently teaches you this glyph.\n\nEach time you shapeshift into Cat Form, your shapeshifted form will be randomly selected.\n11"}
MultiLanguageSpellData['en'][225533] = {name = "Glyph of the Forest Path", additional_info = "2 sec cast\nReagents:\nLight Parchment , Sallow Pigment (4), Roseate Pigment (60)\n[q]Craft a Glyph of the Forest Path.\nVendor:\nLorelae Wintersong\nZone:\nMoonglade\nCost:\n35\n\nClasses: Druid\n[q2]Use: Permanently teaches you this glyph.\n\nYour Dash now leaves a trail of leaves.\n11"}
MultiLanguageSpellData['en'][225534] = {name = "Glyph of Autumnal Bloom", additional_info = "2 sec cast\nReagents:\nLight Parchment , Sallow Pigment (4), Roseate Pigment (60)\n[q]Craft a Glyph of Autumnal Bloom.\nVendor:\nJang Quillpaw\nZone:\nDalaran\nCost:\n35\n\nClasses: Druid\n[q2]Use: Permanently teaches you this glyph.\n\nModifies your Lifebloom to appear as a large blooming autumn flower.\n11"}
MultiLanguageSpellData['en'][225535] = {name = "Glyph of Arachnophobia", additional_info = "2 sec cast\nReagents:\nLight Parchment , Sallow Pigment (8), Roseate Pigment (40)\n[q]Craft a Glyph of Arachnophobia.\nDrop:\nWorld Broken Isles Creatures\n\nClasses: Hunter\n[q2]Use: Permanently teaches you this glyph.\n\nYour Dire Beast ability calls on spiders more often. Why? Because everyone is afraid of spiders. Exclusive with: Glyph of Nesingwary's Nemeses Glyph of the Dire Stable Glyph of Dire Bees\n11"}
MultiLanguageSpellData['en'][225536] = {name = "Glyph of Nesingwary's Nemeses", additional_info = "2 sec cast\nReagents:\nLight Parchment , Sallow Pigment (8), Roseate Pigment (40)\n[q]Craft a Glyph of Nesingwary's Nemeses.\nVendor:\nLucas Sigmund\nZone:\nHighmountain\nCost:\n35\n\nClasses: Hunter\n[q2]Use: Permanently teaches you this glyph.\n\nYour Dire Beast ability often calls for beasts victimized by the famed hunter. Exclusive with: Glyph of Arachnophobia Glyph of the Dire Stable Glyph of Dire Bees\n11"}
MultiLanguageSpellData['en'][225538] = {name = "Glyph of the Dire Stable", additional_info = "2 sec cast\nReagents:\nLight Parchment , Sallow Pigment (8), Roseate Pigment (40)\n[q]Craft a Glyph of the Dire Stable.\nVendor:\nJang Quillpaw\nZone:\nDalaran\nCost:\n35\n\nClasses: Hunter\n[q2]Use: Permanently teaches you this glyph.\n\nYour Dire Beast often calls forth dire versions of your stabled pets. Exclusive with: Glyph of Arachnophobia Glyph of Nesingwary's Nemeses Glyph of Dire Bees\n11"}
MultiLanguageSpellData['en'][225539] = {name = "Glyph of the Goblin Anti-Grav Flare", additional_info = "2 sec cast\nReagents:\nLight Parchment , Sallow Pigment (8), Roseate Pigment (40)\n[q]Craft a Glyph of the Goblin Anti-Grav Flare.\nVendor:\nHobart Grapplehammer\nZone:\nDalaran\nCost:\n35\n\nClasses: Hunter\n[q2]Use: Permanently teaches you this glyph.\n\nExchange your flares with Goblin Anti-Grav Flares! They almost work, and at least they don't explode. Exclusive with: Glyph of Stellar Flare\n11"}
MultiLanguageSpellData['en'][225541] = {name = "Glyph of the Hook", additional_info = "2 sec cast\nReagents:\nLight Parchment , Sallow Pigment (8), Roseate Pigment (40)\n[q]Craft a Glyph of the Hook.\nDrop:\nBroken Isles Murlocs\n\nClasses: Hunter\n[q2]Use: Permanently teaches you this glyph.\n\nYour Harpoon spell throws a Grappling Hook rather than your current weapon. Exclusive with: Glyph of the Trident\n11"}
