MultiLanguageSpellData['en'][225547] = {name = "Glyph of Yu'lon's Grace", additional_info = "2 sec cast\nReagents:\nLight Parchment , Sallow Pigment (4), Roseate Pigment (60)\n[q]Craft a Glyph of Yu'lon's Grace.\nVendor:\nJang Quillpaw\nZone:\nDalaran\nCost:\n35\n\nClasses: Monk\n[q2]Use: Permanently teaches you this glyph.\n\nChanges your Gift of the Ox orbs to take on the green of Yu'lon.\n11"}
MultiLanguageSpellData['en'][225548] = {name = "Glyph of Burnout", additional_info = "2 sec cast\nReagents:\nLight Parchment , Sallow Pigment (10), Roseate Pigment (30)\n[q]Craft a Glyph of Burnout.\nVendor:\nCravitz Lorent\nZone:\nCrystalsong Forest\nZone:\nDalaran Sewers\nCost:\n35\n\nClasses: Rogue\n[q2]Use: Permanently teaches you this glyph.\n\nYour sprint leaves a smoke trail in your wake.\n11"}
MultiLanguageSpellData['en'][225549] = {name = "Glyph of Flash Bang", additional_info = "2 sec cast\nReagents:\nLight Parchment , Sallow Pigment (10), Roseate Pigment (30)\n[q]Craft a Glyph of Flash Bang.\nVendor:\nThe Widow\nZone:\nDalaran Sewers\nCost:\n100\n\nClasses: Rogue\n[q2]Use: Permanently teaches you this glyph.\n\nSwitch out your smoke for a Flash Bang!\n11"}
MultiLanguageSpellData['en'][225550] = {name = "Glyph of Critterhex", additional_info = "2 sec cast\nReagents:\nLight Parchment , Sallow Pigment (6), Roseate Pigment (50)\n[q]Craft a Glyph of Critterhex.\nVendor:\nK'huta\nZone:\nDalaran Sewers\nCost:\n100\n\nClasses: Shaman\n[q2]Use: Permanently teaches you this glyph.\n\nYour Hex on critters lasts 1 day and can be cast on multiple critters.\n11"}
MultiLanguageSpellData['en'][225551] = {name = "Glyph of Flickering", additional_info = "2 sec cast\nReagents:\nLight Parchment , Sallow Pigment (6), Roseate Pigment (50)\n[q]Craft a Glyph of Flickering.\nVendor:\nElementalist Sharvak\nZone:\nNagrand\nCost:\n35\n\nClasses: Shaman\n[q2]Use: Permanently teaches you this glyph.\n\nReduces the size of your Fire Elemental by 15%.\n11"}
MultiLanguageSpellData['en'][225552] = {name = "Glyph of Pebbles", additional_info = "2 sec cast\nReagents:\nLight Parchment , Sallow Pigment (6), Roseate Pigment (50)\n[q]Craft a Glyph of Pebbles.\nDrop:\nBroken Isles Drogbar\n\n\nClasses: Shaman\n[q2]Use: Permanently teaches you this glyph.\n\nReduces the size of your Earth Elemental by 15%.\n11"}
