MultiLanguageSpellData['en'][273847] = {name = "Healing Stream", additional_info = "Instant\n[q]Summons a totem at your feet for 15 sec that heals [ Rushing Streams : two injured party or raid members / an injured party or raid member] within 40 yards for (67.68% of Spell Power) every 2 sec.\n\n If you already know [ Cloudburst Totem : Cloudburst Totem / Healing Stream Totem ], instead gain 1 additional charge of [ Cloudburst Totem : Cloudburst Totem / Healing Stream Totem ]."}
